/* <wakil-agent> — 3D Wakil character. One shared WebGL renderer draws every instance into its own 2D canvas.
   Attributes: color (purple|plum|indigo|teal|sea|forest), hat (chef|songkok|cap|headset|none), face (happy|focus|calm),
   initials, pose (idle|speak|think|happy), turn (deg), spin, interactive, saved (buyer|supplier → reads localStorage). */
(function () {
  if (customElements.get('wakil-agent')) return;
  const THREE_URL = 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
  let T = null, loading = null;
  const LOGO_DATA = {"logos/mak-ngah.png":"data:image/png;base64,","logos/ayam-segar.png":"data:image/png;base64,","logos/kampung-poultry.png":"data:image/png;base64,","logos/fresh-poultry.png":"data:image/png;base64,","logos/seng-huat.png":"data:image/png;base64,","logos/kak-yah.png":"data:image/png;base64,","logos/dapur-catering.png":"data:image/png;base64,"};
  function compat() {
    if (T.ColorManagement) { if ('enabled' in T.ColorManagement) T.ColorManagement.enabled = true; else T.ColorManagement.legacyMode = false; }
  }
  const load = () => loading || (loading = (window.THREE && window.THREE.WebGLRenderer ? Promise.resolve(window.THREE) : import(THREE_URL)).then(m => { T = m; compat(); }));
  const setCS = t => { if ('colorSpace' in t) t.colorSpace = T.SRGBColorSpace; else t.encoding = T.sRGBEncoding; return t; };

  const PAL = {
    purple: { body: '#6A5CF0', head: '#F1EFFC', accent: '#8F87E6', glow: '#CFCBFF' },
    plum:   { body: '#7A3F9E', head: '#F5EEF8', accent: '#B98AD6', glow: '#F0D2FF' },
    indigo: { body: '#3D4AB5', head: '#ECEEFA', accent: '#8792E0', glow: '#C9D0FF' },
    teal:   { body: '#0E8A76', head: '#EBF6F3', accent: '#5FD0B8', glow: '#B6FFEE' },
    sea:    { body: '#1C6E8A', head: '#E9F3F7', accent: '#6CC3E0', glow: '#C2F1FF' },
    forest: { body: '#2F6B45', head: '#EDF5EF', accent: '#7CC795', glow: '#CDFFD9' },
  };
  const DEFAULTS = {
    buyer: { color: 'purple', hat: 'chef', face: 'happy' },
    supplier: { color: 'teal', hat: 'cap', face: 'focus' },
  };
  const KEY = s => 'supplyswipe.wakil.' + s;
  window.WakilAgent = {
    defaults: DEFAULTS, palettes: PAL,
    get(side) { try { return Object.assign({}, DEFAULTS[side], JSON.parse(localStorage.getItem(KEY(side)) || '{}')); } catch (_) { return Object.assign({}, DEFAULTS[side]); } },
    set(side, cfg) { try { localStorage.setItem(KEY(side), JSON.stringify(cfg)); } catch (_) {} window.dispatchEvent(new CustomEvent('wakil-change', { detail: { side } })); },
    reset(side) { try { localStorage.removeItem(KEY(side)); } catch (_) {} window.dispatchEvent(new CustomEvent('wakil-change', { detail: { side } })); },
  };

  const M = { els: new Set(), r: null, S: 640, started: false };
  function ensure() {
    if (M.r) return;
    const r = new T.WebGLRenderer({ antialias: true, alpha: true });
    r.setPixelRatio(1); r.setSize(M.S, M.S, false);
    if ('outputColorSpace' in r) r.outputColorSpace = T.SRGBColorSpace; else r.outputEncoding = T.sRGBEncoding;
    if ('physicallyCorrectLights' in r) r.physicallyCorrectLights = true;
    r.toneMapping = T.ACESFilmicToneMapping; r.toneMappingExposure = 1.0;
    r.setScissorTest(true); r.setClearColor(0x000000, 0);
    M.r = r;
  }
  function loop() {
    requestAnimationFrame(loop);
    const t = performance.now() / 1000, r = M.r;
    for (const el of M.els) {
      if (!el._vis || !el._scene || !el._w) continue;
      try { el._tick(t);
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      let w = Math.round(el._w * dpr), h = Math.round(el._h * dpr);
      const k = Math.min(1, M.S / Math.max(w, h)); w = Math.max(1, Math.round(w * k)); h = Math.max(1, Math.round(h * k));
      const c = el._canvas;
      if (c.width !== w || c.height !== h) { c.width = w; c.height = h; }
      if (el._cam.aspect !== w / h) { el._cam.aspect = w / h; el._cam.updateProjectionMatrix(); }
      r.setViewport(0, 0, w, h); r.setScissor(0, 0, w, h); r.clear();
      r.render(el._scene, el._cam);
      const ctx = el._ctx; ctx.clearRect(0, 0, w, h);
      ctx.drawImage(r.domElement, 0, M.S - h, w, h, 0, 0, w, h);
      } catch (err) { if (!el._warned) { el._warned = true; console.warn('[wakil-agent] render failed, falling back without logo', err); } if (el._b && !el._noLogo) { el._noLogo = true; el._rebuild(); } }
    }
  }

  function texBadge(txt, bg, fg) {
    const c = document.createElement('canvas'); c.width = c.height = 128;
    const g = c.getContext('2d');
    g.fillStyle = bg; g.beginPath(); g.arc(64, 64, 64, 0, Math.PI * 2); g.fill();
    g.fillStyle = fg; g.font = '600 52px "Plus Jakarta Sans", system-ui, sans-serif'; g.textAlign = 'center'; g.textBaseline = 'middle';
    g.fillText(txt, 64, 68);
    return setCS(new T.CanvasTexture(c));
  }
  const LOGO = {};
  function logoTex(url) {
    if (LOGO[url]) return LOGO[url];
    const key = Object.keys(LOGO_DATA).find(k => url.endsWith(k));
    const src = key ? LOGO_DATA[key] : new URL(url, document.baseURI).href;
    const t = setCS(new T.TextureLoader().load(src)); t.anisotropy = 4;
    LOGO[url] = t; return t;
  }
  function texShadow() {
    const c = document.createElement('canvas'); c.width = c.height = 128;
    const g = c.getContext('2d'); const gr = g.createRadialGradient(64, 64, 4, 64, 64, 64);
    gr.addColorStop(0, 'rgba(23,32,28,0.35)'); gr.addColorStop(1, 'rgba(23,32,28,0)');
    g.fillStyle = gr; g.fillRect(0, 0, 128, 128);
    return new T.CanvasTexture(c);
  }

  function build(cfg) {
    const P = PAL[cfg.color] || PAL.purple;
    const scene = new T.Scene();
    const cam = new T.PerspectiveCamera(27, 1, 0.1, 50); if (cfg.bust) { cam.position.set(0, 1.5, 4.4); cam.lookAt(0, 1.45, 0); } else { cam.position.set(0, 1.75, 7.6); cam.lookAt(0, 1.42, 0); }
    scene.add(new T.HemisphereLight(0xffffff, 0xd9d6cf, 1.5));
    const key = new T.DirectionalLight(0xffffff, 2.4); key.position.set(3, 5, 5); scene.add(key);
    const rim = new T.DirectionalLight(new T.Color(P.accent), 1.6); rim.position.set(-4, 3, -3); scene.add(rim);
    const std = (c, o = {}) => new T.MeshStandardMaterial(Object.assign({ color: new T.Color(c), roughness: 0.45, metalness: 0.05 }, o));
    const mBody = std(P.body), mHead = std(P.head, { roughness: 0.35 }), mAcc = std(P.accent);
    const mInk = std('#15191A', { roughness: 0.18, metalness: 0.3 });
    const mGlow = new T.MeshStandardMaterial({ color: new T.Color(P.glow), emissive: new T.Color(P.glow), emissiveIntensity: 1.6, roughness: 0.3 });
    const root = new T.Group(); scene.add(root);
    const shadow = new T.Mesh(new T.CircleGeometry(1.0, 32), new T.MeshBasicMaterial({ map: texShadow(), transparent: true, depthWrite: false }));
    shadow.rotation.x = -Math.PI / 2; shadow.position.y = 0.01; scene.add(shadow);

    const body = new T.Mesh(new T.CapsuleGeometry(0.44, 0.36, 10, 28), mBody); body.position.y = 0.68; root.add(body);
    const badge = new T.Mesh(new T.CircleGeometry(0.2, 40), cfg.logo ? new T.MeshStandardMaterial({ color: new T.Color(P.head), roughness: 0.5 }) : new T.MeshStandardMaterial({ map: texBadge(cfg.initials || 'MN', P.head, P.body), roughness: 0.5 }));
    badge.position.set(0, 0.72, 0.445); root.add(badge);
    if (cfg.logo) {
      const lm = new T.MeshStandardMaterial({ map: logoTex(cfg.logo), transparent: true, roughness: 0.5 });
      const lp = new T.Mesh(new T.PlaneGeometry(0.34, 0.34), lm); lp.position.set(0, 0.72, 0.452); root.add(lp);
    }
    const ring = new T.Mesh(new T.TorusGeometry(0.205, 0.022, 10, 40), mAcc); ring.position.copy(badge.position); root.add(ring);

    const arms = [];
    [-1, 1].forEach(s => {
      const piv = new T.Group(); piv.position.set(s * 0.47, 0.98, 0);
      const a = new T.Mesh(new T.CapsuleGeometry(0.11, 0.28, 8, 16), mBody); a.position.y = -0.24; piv.add(a);
      const hand = new T.Mesh(new T.SphereGeometry(0.12, 20, 16), mHead); hand.position.y = -0.46; piv.add(hand);
      piv.rotation.z = s * 0.22; root.add(piv); arms.push(piv);
    });
    const neck = new T.Mesh(new T.CylinderGeometry(0.16, 0.2, 0.14, 24), mAcc); neck.position.y = 1.18; root.add(neck);

    const head = new T.Group(); head.position.y = 1.6; root.add(head);
    const skull = new T.Mesh(new T.SphereGeometry(0.62, 56, 40), mHead); skull.scale.set(1.14, 0.92, 1.0); head.add(skull);
    const visor = new T.Mesh(new T.SphereGeometry(0.5, 48, 32), mInk); visor.scale.set(1.02, 0.64, 0.56); visor.position.set(0, -0.02, 0.36); head.add(visor);
    const eyes = new T.Group(); eyes.position.set(0, 0.0, 0.64); head.add(eyes);
    [-1, 1].forEach(s => {
      let e;
      if (cfg.face === 'focus') { e = new T.Mesh(new T.BoxGeometry(0.17, 0.045, 0.03), mGlow); e.rotation.z = s * -0.12; }
      else if (cfg.face === 'calm') { e = new T.Mesh(new T.SphereGeometry(0.06, 16, 12), mGlow); e.scale.set(1, 1.25, 0.5); }
      else { e = new T.Mesh(new T.TorusGeometry(0.085, 0.026, 8, 24, Math.PI), mGlow); }
      e.position.x = s * 0.2; eyes.add(e);
    });
    if (cfg.face === 'happy') { const m = new T.Mesh(new T.TorusGeometry(0.06, 0.018, 8, 20, Math.PI), mGlow); m.rotation.z = Math.PI; m.position.set(0, -0.12, 0.63); head.add(m); }
    [-1, 1].forEach(s => { const ear = new T.Mesh(new T.CylinderGeometry(0.11, 0.11, 0.1, 24), cfg.hat === 'headset' ? mInk : mAcc); ear.rotation.z = Math.PI / 2; ear.position.set(s * 0.7, 0, 0); head.add(ear); });

    let tip = null;
    const top = 0.57;
    if (cfg.hat === 'none' || cfg.hat === 'headset' || !cfg.hat) {
      const stick = new T.Mesh(new T.CylinderGeometry(0.022, 0.022, 0.26, 10), mAcc); stick.position.y = top + 0.13; head.add(stick);
      tip = new T.Mesh(new T.SphereGeometry(0.075, 20, 16), mGlow); tip.position.y = top + 0.29; head.add(tip);
    }
    if (cfg.hat === 'chef') {
      const mW = std('#FFFFFF', { roughness: 0.8 });
      const band = new T.Mesh(new T.CylinderGeometry(0.5, 0.47, 0.36, 40), mW); band.position.y = top + 0.12; head.add(band);
      [[-0.22, 0.42, 0.05], [0.22, 0.42, 0.05], [0, 0.5, -0.08], [0, 0.44, 0.18]].forEach(p => { const b = new T.Mesh(new T.SphereGeometry(0.27, 24, 18), mW); b.position.set(p[0], top + p[1], p[2]); head.add(b); });
    } else if (cfg.hat === 'songkok') {
      const mS = std('#1C1B22', { roughness: 0.95 });
      const s = new T.Mesh(new T.CylinderGeometry(0.5, 0.55, 0.36, 48), mS); s.position.y = top + 0.04; head.add(s);
    } else if (cfg.hat === 'cap') {
      const dome = new T.Mesh(new T.SphereGeometry(0.62, 48, 24, 0, Math.PI * 2, 0, Math.PI / 2), mAcc); dome.scale.set(1.12, 0.72, 1.04); dome.position.y = 0.2; head.add(dome);
      const brim = new T.Mesh(new T.CylinderGeometry(0.42, 0.42, 0.035, 40, 1, false, -Math.PI / 2, Math.PI), mAcc); brim.position.set(0, 0.22, 0.52); head.add(brim);
      const btn = new T.Mesh(new T.SphereGeometry(0.06, 12, 10), mBody); btn.position.y = 0.66; head.add(btn);
    } else if (cfg.hat === 'headset') {
      const band = new T.Mesh(new T.TorusGeometry(0.7, 0.04, 12, 48, Math.PI), mInk); band.position.y = 0.02; head.add(band);
      [-1, 1].forEach(s => { const cup = new T.Mesh(new T.CylinderGeometry(0.17, 0.17, 0.12, 28), mInk); cup.rotation.z = Math.PI / 2; cup.position.set(s * 0.74, 0, 0); head.add(cup); });
      const boom = new T.Mesh(new T.CylinderGeometry(0.018, 0.018, 0.5, 8), mInk); boom.position.set(-0.6, -0.22, 0.32); boom.rotation.set(0.9, 0, 0.9); head.add(boom);
      const mic = new T.Mesh(new T.SphereGeometry(0.055, 14, 12), mGlow); mic.position.set(-0.38, -0.36, 0.55); head.add(mic);
    }
    return { scene, cam, root, head, arms, eyes, tip, mGlow };
  }

  if (!document.getElementById('wakil-agent-css')) { const st = document.createElement('style'); st.id = 'wakil-agent-css'; st.textContent = 'wakil-agent{display:block;position:relative}wakil-agent>canvas{position:absolute;inset:0;width:100%;height:100%;display:block;pointer-events:none}'; document.head.appendChild(st); }
  class WakilAgent extends HTMLElement {
    static get observedAttributes() { return ['color', 'hat', 'face', 'initials', 'logo', 'pose', 'turn', 'spin', 'saved']; }
    constructor() {
      super();
      this._yaw = 0; this._userYaw = 0; this._phase = Math.random() * 6; this._vis = true;
      this._onChange = e => { if (!e.detail || e.detail.side === this.getAttribute('saved')) this._rebuild(); };
    }
    connectedCallback() {
      if (!this._canvas) {
        const c = document.createElement('canvas'); c.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;display:block;pointer-events:none';
        this.appendChild(c); this._canvas = c; this._ctx = c.getContext('2d');
      }
      this._ro = new ResizeObserver(() => { this._w = this.clientWidth; this._h = this.clientHeight; }); this._ro.observe(this);
      this._w = this.clientWidth; this._h = this.clientHeight;
      this._io = new IntersectionObserver(es => { this._vis = es[0].isIntersecting; }); this._io.observe(this);
      window.addEventListener('wakil-change', this._onChange); window.addEventListener('storage', this._onChange);
      if (this.hasAttribute('interactive')) this._bindDrag();
      M.els.add(this);
      load().then(() => { ensure(); if (!M.started) { M.started = true; loop(); } this._rebuild(); });
    }
    disconnectedCallback() {
      M.els.delete(this); this._ro && this._ro.disconnect(); this._io && this._io.disconnect();
      window.removeEventListener('wakil-change', this._onChange); window.removeEventListener('storage', this._onChange);
      this._dispose();
    }
    attributeChangedCallback(n) { if (['color', 'hat', 'face', 'initials', 'logo', 'saved'].includes(n) && T) this._rebuild(); }
    _cfg() {
      const side = this.getAttribute('saved');
      const base = { color: this.getAttribute('color') || 'purple', hat: this.getAttribute('hat') || 'none', face: this.getAttribute('face') || 'happy', initials: this.getAttribute('initials') || 'MN', logo: this._noLogo ? '' : (this.getAttribute('logo') || ''), bust: this.hasAttribute('bust') };
      if (side && window.WakilAgent) { const s = window.WakilAgent.get(side); base.color = s.color; base.hat = s.hat; base.face = s.face; }
      return base;
    }
    _dispose() { if (this._scene) this._scene.traverse(o => { o.geometry && o.geometry.dispose(); if (o.material) { if (o.material.map && !Object.values(LOGO).includes(o.material.map)) o.material.map.dispose(); o.material.dispose(); } }); }
    _rebuild() { if (!T) return; this._dispose(); const b = build(this._cfg()); Object.assign(this, { _scene: b.scene, _cam: b.cam, _b: b }); }
    _bindDrag() {
      let x0 = null, y0 = 0;
      this.style.cursor = 'grab'; this.style.touchAction = 'none';
      this.addEventListener('pointerdown', e => { x0 = e.clientX; y0 = this._userYaw; try { this.setPointerCapture(e.pointerId); } catch (_) {} this._dragging = true; });
      this.addEventListener('pointermove', e => { if (x0 != null) this._userYaw = y0 + (e.clientX - x0) * 0.012; });
      const end = () => { x0 = null; this._dragging = false; };
      this.addEventListener('pointerup', end); this.addEventListener('pointercancel', end);
    }
    _tick(t) {
      const b = this._b; if (!b) return;
      const pose = this.getAttribute('pose') || 'idle';
      const tt = t + this._phase;
      let target = (parseFloat(this.getAttribute('turn')) || 0) * Math.PI / 180 + this._userYaw;
      if (this.hasAttribute('spin') && !this._dragging) { this._userYaw += 0.008; }
      this._yaw += (target - this._yaw) * 0.12;
      b.root.rotation.y = this._yaw;
      let y = Math.sin(tt * 2) * 0.035, hz = Math.sin(tt * 1.3) * 0.03, hx = 0;
      let aL = 0.22 + Math.sin(tt * 1.6) * 0.05, aR = -0.22 - Math.sin(tt * 1.6) * 0.05, glow = 1.4;
      if (pose === 'speak') { hz = Math.sin(tt * 6) * 0.07; hx = Math.sin(tt * 3) * 0.05; aR = -1.1 + Math.sin(tt * 8) * 0.35; glow = 1.8 + Math.sin(tt * 12) * 0.8; y = Math.sin(tt * 4) * 0.05; }
      else if (pose === 'think') { hz = 0.16; hx = -0.06; aL = 0.9; glow = 0.8 + (Math.sin(tt * 5) > 0 ? 1.2 : 0); }
      else if (pose === 'happy') { y = Math.abs(Math.sin(tt * 4.5)) * 0.18; aL = 2.5 + Math.sin(tt * 9) * 0.2; aR = -2.5 - Math.sin(tt * 9) * 0.2; glow = 2.4; }
      b.root.position.y = y;
      b.head.rotation.z += (hz - b.head.rotation.z) * 0.15; b.head.rotation.x += (hx - b.head.rotation.x) * 0.15;
      b.arms[0].rotation.z += (-aL - b.arms[0].rotation.z) * 0.15; b.arms[1].rotation.z += (-aR - b.arms[1].rotation.z) * 0.15;
      b.mGlow.emissiveIntensity = glow;
      const blink = (tt % 3.8) < 0.12 ? 0.15 : 1; b.eyes.scale.y += (blink - b.eyes.scale.y) * 0.5;
    }
  }
  customElements.define('wakil-agent', WakilAgent);
})();
